-- Baseline for a NEW empty MySQL 8 database. No demo/business rows.
-- Existing databases require reviewed schema comparison and explicit baseline; see DATABASE_SETUP.md.
create table beat_plan_entries (visit_order integer not null, beat_plan_id bigint not null, customer_id bigint not null, id bigint not null auto_increment, organization_id bigint not null, day_of_week enum ('MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY') not null, primary key (id)) engine=InnoDB;
create table beat_plans (is_active bit not null, created_at datetime(6) not null, id bigint not null auto_increment, organization_id bigint not null, salesperson_id bigint not null, name varchar(255) not null, primary key (id)) engine=InnoDB;
create table customers (credit_balance float(53) not null, credit_limit float(53) not null, created_at datetime(6) not null, id bigint not null auto_increment, organization_id bigint not null, version bigint, address varchar(255), customer_name varchar(255) not null, email varchar(255), gst_number varchar(255), phone varchar(255), status enum ('ACTIVE','INACTIVE') not null, primary key (id)) engine=InnoDB;
create table deliveries (assigned_at datetime(6) not null, delivered_at datetime(6), delivery_person_id bigint, generated_invoice_id bigint, id bigint not null auto_increment, organization_id bigint not null, sales_order_id bigint not null, started_at datetime(6), version bigint default 0 not null, delivery_notes varchar(500), delivery_number varchar(255) not null, receiver_name varchar(255), receiver_phone varchar(255), vehicle_number varchar(255), failure_reason enum ('SHOP_CLOSED','CUSTOMER_UNAVAILABLE','GOODS_REJECTED','ADDRESS_ISSUE','PAYMENT_DISPUTE','OTHER'), status enum ('ASSIGNED','OUT_FOR_DELIVERY','DELIVERED','PARTIALLY_DELIVERED','FAILED','CANCELLED') not null, primary key (id)) engine=InnoDB;
create table delivery_items (delivered_quantity integer not null, delivering_quantity integer not null, ordered_quantity integer not null, unit_price float(53) not null, delivery_id bigint not null, id bigint not null auto_increment, product_id bigint not null, primary key (id)) engine=InnoDB;
create table goods_receipt_items (ordered_qty float(53) not null, received_qty float(53) not null, unit_price float(53) not null, id bigint not null auto_increment, organization_id bigint not null, product_id bigint not null, receipt_id bigint not null, primary key (id)) engine=InnoDB;
create table goods_receipts (created_at datetime(6) not null, id bigint not null auto_increment, organization_id bigint not null, purchase_id bigint not null, received_date datetime(6) not null, receipt_number varchar(255) not null, primary key (id)) engine=InnoDB;
create table organization_invites (created_at datetime(6) not null, expires_at datetime(6) not null, id bigint not null auto_increment, invited_by_id bigint not null, organization_id bigint not null, invitee_phone_number varchar(255) not null, status varchar(255) not null, token varchar(255) not null, role enum ('ADMIN','MANAGER','ACCOUNTANT','SALES','WAREHOUSE') not null, primary key (id)) engine=InnoDB;
create table organization_memberships (is_active bit not null, id bigint not null auto_increment, joined_at datetime(6) not null, organization_id bigint not null, user_id bigint not null, role enum ('ADMIN','MANAGER','ACCOUNTANT','SALES','WAREHOUSE') not null, primary key (id)) engine=InnoDB;
create table organizations (created_at datetime(6) not null, id bigint not null auto_increment, name varchar(255) not null, primary key (id)) engine=InnoDB;
create table otp_verification (attempts integer not null, verified bit not null, created_at datetime(6) not null, expires_at datetime(6) not null, id bigint not null auto_increment, otp_code varchar(255) not null, phone_number varchar(255) not null, primary key (id)) engine=InnoDB;
create table payment_sale_allocations (amount float(53) not null, payment_id bigint not null, sale_id bigint not null, primary key (payment_id, sale_id)) engine=InnoDB;
create table payments (amount float(53) not null, opening_balance_amount float(53), id bigint not null auto_increment, organization_id bigint not null, payment_date datetime(6) not null, reference_id bigint not null, client_reference_id varchar(64), payment_mode enum ('CASH','UPI','CARD','CREDIT') not null, reference_type enum ('SALE','PURCHASE','CUSTOMER','SUPPLIER') not null, primary key (id)) engine=InnoDB;
create table price_history (price float(53) not null, effective_from datetime(6) not null, id bigint not null auto_increment, organization_id bigint not null, product_id bigint not null, price_type enum ('PURCHASE','SELLING') not null, primary key (id)) engine=InnoDB;
create table products (gst_rate float(53) not null, minimum_stock float(53) not null, purchase_price float(53) not null, selling_price float(53) not null, stock float(53) not null, created_at datetime(6) not null, id bigint not null auto_increment, organization_id bigint not null, version bigint, brand varchar(255), category varchar(255), hsn_code varchar(255), product_name varchar(255) not null, unit varchar(255), status enum ('ACTIVE','INACTIVE') not null, primary key (id)) engine=InnoDB;
create table purchase (total_amount float(53) not null, created_at datetime(6) not null, id bigint not null auto_increment, organization_id bigint not null, purchase_date datetime(6) not null, supplier_id bigint not null, invoice_number varchar(255) not null, status enum ('DRAFT','PENDING_APPROVAL','APPROVED','ORDERED','PARTIALLY_RECEIVED','RECEIVED','COMPLETED','CANCELLED') not null, primary key (id)) engine=InnoDB;
create table purchase_items (price float(53) not null, quantity float(53) not null, id bigint not null auto_increment, organization_id bigint not null, product_id bigint not null, purchase_id bigint not null, primary key (id)) engine=InnoDB;
create table purchase_returns (quantity_returned float(53) not null, id bigint not null auto_increment, organization_id bigint not null, product_id bigint not null, purchase_id bigint not null, return_date datetime(6) not null, reason varchar(255), primary key (id)) engine=InnoDB;
create table reconciliation_results (amount_matched float(53) not null, amount_on_invoice float(53) not null, amount_on_purchase float(53) not null, id bigint not null auto_increment, invoice_id bigint not null, organization_id bigint not null, purchase_id bigint not null, reconciled_at datetime(6) not null, details TEXT, status enum ('MATCHED','MISMATCHED') not null, primary key (id)) engine=InnoDB;
create table role_permissions (allowed bit not null, id bigint not null auto_increment, organization_id bigint, permission varchar(64) not null, org_role enum ('ADMIN','MANAGER','ACCOUNTANT','SALES','WAREHOUSE') not null, primary key (id)) engine=InnoDB;
create table sales (cgst float(53) not null, discount float(53) not null, grand_total float(53) not null, igst float(53) not null, sgst float(53) not null, total float(53) not null, created_at datetime(6) not null, customer_id bigint, delivery_id bigint, id bigint not null auto_increment, organization_id bigint not null, sale_date datetime(6) not null, sales_order_id bigint, client_reference_id varchar(64), bill_number varchar(255) not null, customer_name varchar(255), payment_mode enum ('CASH','UPI','CARD','CREDIT') not null, primary key (id)) engine=InnoDB;
create table sales_items (price float(53) not null, quantity float(53) not null, id bigint not null auto_increment, organization_id bigint not null, product_id bigint not null, sale_id bigint not null, primary key (id)) engine=InnoDB;
create table sales_order_items (delivered_quantity integer not null, ordered_quantity integer not null, packed_quantity integer not null, remaining_quantity integer not null, total_price float(53) not null, unit_price float(53) not null, id bigint not null auto_increment, product_id bigint not null, sales_order_id bigint not null, primary key (id)) engine=InnoDB;
create table sales_orders (discount float(53) not null, expected_delivery_date date, grand_total float(53) not null, subtotal float(53) not null, tax_amount float(53) not null, created_at datetime(6) not null, customer_id bigint not null, id bigint not null auto_increment, order_date datetime(6) not null, organization_id bigint not null, salesperson_id bigint, updated_at datetime(6), version bigint default 0 not null, notes varchar(500), order_number varchar(255) not null, status enum ('DRAFT','CONFIRMED','PROCESSING','READY_FOR_DELIVERY','OUT_FOR_DELIVERY','PARTIALLY_DELIVERED','DELIVERED','CANCELLED') not null, primary key (id)) engine=InnoDB;
create table stock_adjustments (quantity_change float(53) not null, adjusted_at datetime(6) not null, id bigint not null auto_increment, organization_id bigint not null, product_id bigint not null, reason varchar(255) not null, primary key (id)) engine=InnoDB;
create table stock_movements (quantity float(53) not null, created_at datetime(6) not null, id bigint not null auto_increment, organization_id bigint not null, product_id bigint not null, reference_id bigint, movement_type enum ('PURCHASE_RECEIPT','SALE','ADJUSTMENT','RETURN','OPENING_STOCK') not null, primary key (id)) engine=InnoDB;
create table supplier_invoice_items (quantity float(53) not null, total_amount float(53) not null, unit_price float(53) not null, id bigint not null auto_increment, invoice_id bigint not null, organization_id bigint not null, product_id bigint not null, primary key (id)) engine=InnoDB;
create table supplier_invoices (total_amount float(53) not null, created_at datetime(6) not null, id bigint not null auto_increment, invoice_date datetime(6), organization_id bigint not null, purchase_id bigint, supplier_id bigint not null, invoice_number varchar(255) not null, status enum ('RECEIVED','MATCHED','MISMATCHED','PAID') not null, primary key (id)) engine=InnoDB;
create table supplier_products (lead_time_days integer, min_order_qty float(53), purchase_price float(53) not null, id bigint not null auto_increment, organization_id bigint not null, product_id bigint not null, supplier_id bigint not null, primary key (id)) engine=InnoDB;
create table suppliers (rating float(53) not null, created_at datetime(6) not null, id bigint not null auto_increment, organization_id bigint not null, address varchar(255), category varchar(255), email varchar(255), gst_number varchar(255), phone varchar(255) not null, supplier_name varchar(255) not null, status enum ('ACTIVE','INACTIVE') not null, primary key (id)) engine=InnoDB;
create table user_profile (user_id bigint not null, email varchar(255), gst_no varchar(255), location varchar(255), register_number varchar(255), primary key (user_id)) engine=InnoDB;
create table users (is_active bit not null, profile_completed bit not null, created_at datetime(6) not null, id bigint not null auto_increment, name varchar(255) not null, password_hash varchar(255), phone_number varchar(255) not null, platform_role enum ('MASTER_ADMIN','USER') not null, primary key (id)) engine=InnoDB;
create table visit_check_ins (latitude float(53), longitude float(53), check_in_time datetime(6), check_out_time datetime(6), customer_id bigint not null, id bigint not null auto_increment, organization_id bigint not null, payment_id bigint, sale_id bigint, salesperson_id bigint not null, visit_schedule_id bigint not null, notes TEXT, outcome enum ('ORDER_PLACED','PAYMENT_COLLECTED','BOTH','NO_ORDER','SHOP_CLOSED','CUSTOMER_UNAVAILABLE','FOLLOW_UP'), primary key (id)) engine=InnoDB;
create table visit_schedules (scheduled_date date not null, visit_order integer not null, beat_plan_id bigint, customer_id bigint not null, id bigint not null auto_increment, organization_id bigint not null, salesperson_id bigint not null, status enum ('PENDING','COMPLETED','MISSED') not null, primary key (id)) engine=InnoDB;
